import React from 'react';
import { useParams } from 'react-router-dom';
import ChatInterface from './ChatInterface/ChatInterface';
import ProcessVisualization from './ProcessVisualization/ProcessVisualization';

// Basic ProcessPage component
const ProcessPage = () => {
  let { processId } = useParams();

  const pageStyle = {
    display: 'flex',
    flexDirection: 'row',
    height: 'calc(100vh - 100px)', // Adjust based on header height, approx
    width: '100%',
    padding: 'var(--spacing-unit, 16px)',
    gap: 'var(--spacing-unit, 16px)',
    boxSizing: 'border-box' // Ensure padding and gap are included in width/height calculations
  };

  const panelStyle = {
    flex: '1 1 50%', // Each panel takes 50% of the width, can grow and shrink
    overflow: 'auto', // Add scroll if content overflows
    // border: '1px solid blue' // For debugging layout
  };

  return (
    <div style={pageStyle}>
      <div style={panelStyle}>
        <ChatInterface processId={processId} />
      </div>
      <div style={panelStyle}>
        <ProcessVisualization processId={processId} />
      </div>
    </div>
  );
};

export default ProcessPage;
